import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, openSync, closeSync, lstatSync, realpathSync, fsyncSync } from "node:fs";
import { dirname, basename, isAbsolute } from "node:path";
/** Root-supplied per-turn paid admission. No policy is generated by the live worker. */
export interface PaidBinding { fixtureSha: string; protocolSha: string; sourceFreezeSha: string; runtimeSha: string; promptSha: string; proofSha: string }
export interface PaidPolicy extends PaidBinding {
  purpose: "review" | "current" | "generation"; grantNonce: string; consumedMarkerPath: string; version: 1; issue: 839; authorizationUrl: string; allowOverage: true; basis: "actual additional billed charges";
  perIssueCapUsd: 15; aggregateCapUsd: 150; remainingUpperUsd: number; issuedAt: string; expiresAt: string; canonicalModel: "claude-sonnet-5-5";
  maxPhysicalRequests: number; maxInputBytes: number; maxInputTokens: 1000000; contextWindowTokens: 1000000; maxOutputTokens: number;
  inputUsdPerMillionUpper: 8; outputUsdPerMillionUpper: 20; invoiceUsd: null;
}
export const AUTHORIZATION_URL = "https://github.com/schlessera/brain-kit/issues/838#issuecomment-6065882737";
export const integer = (n: unknown): n is number => typeof n === "number" && Number.isSafeInteger(n) && n >= 0;
export function assertPaidPolicy(value: unknown, expected: PaidBinding, now = Date.now()): PaidPolicy {
  const p = value as PaidPolicy;
  if (!p || !["review","current","generation"].includes(p.purpose) || !/^[a-f0-9]{64}$/.test(p.grantNonce) || !isAbsolute(p.consumedMarkerPath ?? "") || basename(p.consumedMarkerPath) !== `${p.grantNonce}.json` || p.version !== 1 || p.issue !== 839 || p.authorizationUrl !== AUTHORIZATION_URL || p.allowOverage !== true ||
    p.basis !== "actual additional billed charges" || p.perIssueCapUsd !== 15 || p.aggregateCapUsd !== 150 || p.invoiceUsd !== null ||
    p.canonicalModel !== "claude-sonnet-5-5" || p.inputUsdPerMillionUpper !== 8 || p.outputUsdPerMillionUpper !== 20 ||
    p.contextWindowTokens !== 1000000 || p.maxInputTokens !== 1000000 || !integer(p.maxOutputTokens) || p.maxOutputTokens < 1 || p.maxOutputTokens > 128000 ||
    !integer(p.maxInputBytes) || p.maxInputBytes < 1 || !integer(p.maxPhysicalRequests) || p.maxPhysicalRequests < 1 || p.maxPhysicalRequests > 24 ||
    !Number.isFinite(p.remainingUpperUsd) || p.remainingUpperUsd <= 0 || p.remainingUpperUsd > 15 ||
    !Number.isFinite(Date.parse(p.issuedAt)) || Date.parse(p.issuedAt) > now || !Number.isFinite(Date.parse(p.expiresAt)) || Date.parse(p.expiresAt) <= Date.parse(p.issuedAt) || Date.parse(p.expiresAt) <= now ||
    ["fixtureSha", "protocolSha", "sourceFreezeSha", "runtimeSha", "promptSha", "proofSha"].some(key => { const hash = expected[key as keyof PaidBinding]; return !/^[a-f0-9]{64}$/.test(hash) || p[key as keyof PaidBinding] !== hash; })) throw Error("Root paid policy absent, expired, or not exact-bound");
  return p;
}
/** Installed SDK283 declaration: allowed / allowed_warning / rejected; retain flags, never infer an invoice. */
export function overageAllowed(info: any, paid: boolean) {
  if (!info || !["allowed", "allowed_warning", "rejected"].includes(info.status) || (info.overageStatus !== undefined && !["allowed", "allowed_warning"].includes(info.overageStatus)) || info.overageDisabledReason) return false;
  const active=info.isUsingOverage===true || info.overageInUse===true;
  if (active && (!paid || !["allowed","allowed_warning"].includes(info.overageStatus))) return false;
  if (info.status === "rejected") return paid && info.isUsingOverage === true && ["allowed", "allowed_warning"].includes(info.overageStatus);
  return paid || (info.isUsingOverage !== true && info.overageInUse !== true && (info.isUsingOverage === false || info.overageInUse === false));
}
export class PaidSpend {
  private activeOutputTokens = 0; private activeInputTokens = 0; private activeReserved = 0;
  retainedUpperUsd = 0; inFlight = false; stopped = false; physicalRequests = 0;
  constructor(readonly policy: PaidPolicy, readonly expected: PaidBinding, readonly now = () => Date.now()) { assertPaidPolicy(policy, expected, now()); }
  reserve(bytes: number, body: any) {
    assertPaidPolicy(this.policy, this.expected, this.now());
    if (this.stopped || this.inFlight || this.physicalRequests >= this.policy.maxPhysicalRequests || !integer(bytes) || bytes > this.policy.maxInputBytes ||
      body.model !== this.policy.canonicalModel || !integer(body.max_tokens) || body.max_tokens < 1 || body.max_tokens > this.policy.maxOutputTokens ||
      (body.speed !== undefined && body.speed !== "standard") || (body.service_tier !== undefined && !["standard_only","auto"].includes(body.service_tier)) ||
      (body.inference_geo !== undefined && !["global","us"].includes(body.inference_geo)) || body.fast_mode || body.region || body.priority) throw Error("Paid physical admission refused: bounds, modifiers, concurrency, or prior failure");
    // Token-counting is an estimate, not a financial ceiling: https://platform.claude.com/docs/en/build-with-claude/token-counting
    // Reserve the full root-approved context; bytes only enforce transport integrity.
    const inputTokenCeiling = Math.min(this.policy.maxInputTokens, this.policy.contextWindowTokens);
    const upper = (inputTokenCeiling * 8 + body.max_tokens * 20) / 1000000;
    if (this.retainedUpperUsd + upper > this.policy.remainingUpperUsd) throw Error("Paid physical worst-case reservation exceeds remaining root allowance");
    this.activeInputTokens = inputTokenCeiling; this.activeReserved = upper; this.activeOutputTokens = body.max_tokens; this.retainedUpperUsd += upper; this.physicalRequests++; this.inFlight = true;
    return upper;
  }
  complete(reserved: number, usage: any) {
    const fields = ["input_tokens", "output_tokens", "cache_read_input_tokens", "cache_creation_input_tokens"];
    if (fields.some(field => !integer(usage?.[field]))) { this.fail(); throw Error("Unknown required physical usage; retain worst-case reservation"); }
    const input = usage.input_tokens + usage.cache_read_input_tokens + usage.cache_creation_input_tokens;
    const upper = (input * 8 + usage.output_tokens * 20) / 1000000;
    if (!this.inFlight || reserved !== this.activeReserved || input > this.activeInputTokens || usage.output_tokens > this.activeOutputTokens || upper > reserved) { this.fail(); throw Error("Physical usage exceeds the root conservative reservation"); }
    this.retainedUpperUsd += upper - reserved; this.inFlight = false;
    return upper; // Usage-derived conservative reserve; never an invoice.
  }
  fail() { this.stopped = true; this.inFlight = false; }
}

/** Run on the literal body immediately before forwarding, not merely in main(). */
export function assertPhysicalScope(body: any, policy: PaidPolicy, scope: "review" | "current" | "generation") {
  if (policy.purpose!==scope || !["review","current","generation"].includes(scope) || !Array.isArray(body.messages)) throw Error("Unknown physical purpose/message scope");
  const texts=body.messages.filter((m:any)=>m.role==="user").flatMap((m:any)=>typeof m.content==="string"?[m.content]:Array.isArray(m.content)?m.content.filter((b:any)=>b.type==="text").map((b:any)=>b.text):[]);
  if(scope==="review" && texts.filter((text:unknown)=>typeof text==="string"&&createHash("sha256").update(text).digest("hex")===policy.promptSha).length!==1)throw Error("Literal physical prompt differs from root binding");
  if(scope==="review" && (!Array.isArray(body.tools) || body.tools.length || body.output_config?.effort!=="low"))throw Error("Readonly review tools/effort differ from exact scope");
}

/** Coordinator supplies this protected single-use path; failures never unconsume it. */
export function consumeGrant(policy: PaidPolicy, expected: PaidBinding, now = Date.now()) {
  assertPaidPolicy(policy,expected,now);
  const parent=dirname(policy.consumedMarkerPath),stat=lstatSync(parent);
  if(!stat.isDirectory() || stat.isSymbolicLink() || realpathSync(parent)!==parent || stat.uid!==process.getuid?.() || (stat.mode&0o077)!==0)throw Error("Protected coordinator grant parent required");
  const sha=(value:string)=>createHash("sha256").update(value).digest("hex");
  const marker={version:1,grantNonce:policy.grantNonce,policySha:sha(JSON.stringify(policy)),bindingSha:sha(JSON.stringify(expected)),claimedAtUtc:new Date(now).toISOString(),invoiceUsd:null};
  const fd=openSync(policy.consumedMarkerPath,"wx",0o600);
  try{writeFileSync(fd,JSON.stringify(marker,null,2));fsyncSync(fd);}finally{closeSync(fd);}
  return { marker, sha:sha(readFileSync(policy.consumedMarkerPath,"utf8")) };
}
